package com.dynasty.blueprint.artifact;

import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.entity.animal.Cow;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.entity.monster.Zombie;
import net.minecraft.world.item.*;
import net.minecraftforge.gametest.*;
import java.util.*;

/** Eight native acceptance sources; none run while the user's Java testing is paused. */
@GameTestHolder("dynasty_army") @PrefixGameTestTemplate(false)
public final class ZhanluGameTests {
    @AfterBatch(batch="zhanlu_artifact") public static void release(ServerLevel w){ArtifactGameTests.release(w);}
    private static ServerPlayer player(GameTestHelper h){var p=ArtifactGameTests.player(h);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(ArtifactContent.ZHANLU.get()));p.getFoodData().setFoodLevel(18);p.getFoodData().setSaturation(0);h.onEachTick(()->p.setOnGround(true));return p;}
    private static Zombie enemy(GameTestHelper h,ServerPlayer p,double x,double z){var m=ArtifactGameTests.own(h,EntityType.ZOMBIE.create(h.getLevel()));m.moveTo(p.getX()+x,p.getY(),p.getZ()+z,0,0);m.setNoAi(true);m.setNoGravity(true);m.getAttribute(Attributes.MAX_HEALTH).setBaseValue(1000);m.getAttribute(Attributes.KNOCKBACK_RESISTANCE).setBaseValue(1);m.setHealth(1000);m.setCanPickUpLoot(true);var sword=new ItemStack(Items.DIAMOND_SWORD);sword.setDamageValue(7);sword.getOrCreateTag().putString("DynastyTestOwner","original");m.setItemInHand(InteractionHand.MAIN_HAND,sword);m.setItemInHand(InteractionHand.OFF_HAND,new ItemStack(Items.SHIELD));h.getLevel().addFreshEntity(m);return m;}
    private static Cow target(GameTestHelper h,ServerPlayer p,double x,double z){var c=ArtifactGameTests.own(h,EntityType.COW.create(h.getLevel()));c.moveTo(p.getX()+x,p.getY(),p.getZ()+z,0,0);c.setNoAi(true);c.setNoGravity(true);c.getAttribute(Attributes.MAX_HEALTH).setBaseValue(1000);c.getAttribute(Attributes.KNOCKBACK_RESISTANCE).setBaseValue(1);c.setHealth(1000);h.getLevel().addFreshEntity(c);return c;}
    private static ZhanluField field(GameTestHelper h,ServerPlayer p){var f=ArtifactGameTests.own(h,ArtifactContent.ZHANLU_FIELD.get().create(h.getLevel()));p.startUsingItem(InteractionHand.MAIN_HAND);f.begin(p,p.blockPosition());p.getPersistentData().putUUID("DynastyZhanluField",f.getUUID());h.getLevel().addFreshEntity(f);return f;}
    private static void heldRestored(GameTestHelper h,Zombie m){h.assertTrue(m.getMainHandItem().is(Items.DIAMOND_SWORD)&&m.getMainHandItem().getDamageValue()==7&&m.getMainHandItem().getTag().getString("DynastyTestOwner").equals("original")&&m.getOffhandItem().is(Items.SHIELD)&&m.canPickUpLoot()&&!ZhanluField.disarmed(m),"Original actual equipment, metadata and pickup policy restore once");}
    @GameTest(template="cauldron_pit_test",timeoutTicks=10,batch="zhanlu_artifact")
    public static void nativeGuardWindowGrowsWithMissingHealthWithoutPermanentShield(GameTestHelper h){var p=player(h);h.assertTrue(ZhanluAbility.guardTicks(p)==3&&!p.getMainHandItem().canPerformAction(net.minecraftforge.common.ToolActions.SHIELD_BLOCK),"Full health gives3ticks; sword stance is not a permanent native shield");p.setHealth(100);h.assertTrue(ZhanluAbility.guardTicks(p)==11,"Ninety-percent missing health gives eleven native guard ticks");var boss=ArtifactGameTests.own(h,com.dynasty.blueprint.boss.BlindMarshalContent.MARSHAL.get().create(h.getLevel()));h.assertTrue(!ZhanluAbility.susceptible(boss),"Real4metre visual glaive is not an empty native hand");h.succeed();}
    @GameTest(template="cauldron_pit_test",timeoutTicks=190,batch="zhanlu_artifact")
    public static void fourNativeCutsHaveDifferentGeometryAndHealthGatedDurability(GameTestHelper h){var p=player(h);var front=target(h,p,0,2);var diagonal=target(h,p,1.35,1.5);for(int i=0;i<4;i++){int cut=i;h.runAfterDelay(80+20*i,()->{h.assertTrue(ArtifactCombat.swing(p)&&p.getMainHandItem().getTag().getInt("DynastyZhanluCut")==cut,"Server chooses next real cut");});}h.runAfterDelay(155,()->{h.assertTrue(Math.abs(front.getHealth()-880)<.01&&Math.abs(diagonal.getHealth()-970)<.01,"Four30point unarmed true hits; only broad draw reaches diagonal victim");h.assertTrue(p.getMainHandItem().getDamageValue()==0,"Above80percent health costs no durability");p.setHealth(800);});h.runAfterDelay(165,()->{h.assertTrue(ArtifactCombat.swing(p)&&p.getMainHandItem().getDamageValue()==1,"Exactly80percent costs one durability on an accepted hit");h.succeed();});}
    @GameTest(template="cauldron_pit_test",timeoutTicks=115,batch="zhanlu_artifact")
    public static void twentyTickWindupFourSecondDisarmAndThirtyPercentHeal(GameTestHelper h){var p=player(h);p.setHealth(600);var m=enemy(h,p,0,3);double base=m.getAttributeValue(Attributes.MOVEMENT_SPEED);h.runAfterDelay(4,()->{h.assertTrue(ArtifactAbility.begin(p,p.getMainHandItem()),"Native server session begins");p.startUsingItem(InteractionHand.MAIN_HAND);});h.runAfterDelay(23,()->h.assertTrue(h.getLevel().getEntitiesOfClass(ZhanluField.class,p.getBoundingBox().inflate(6),f->f.ownedBy(p)).isEmpty(),"Nineteen ticks do not open field"));h.runAfterDelay(26,()->h.assertTrue(m.getMainHandItem().isEmpty()&&m.getOffhandItem().isEmpty()&&Math.abs(m.getAttributeValue(Attributes.MOVEMENT_SPEED)-base*.3)<1e-8,"Both real hands leased; exactly seventy-percent attribute reduction"));h.runAfterDelay(80,()->{float health=p.getHealth();p.hurt(p.damageSources().mobAttack(m),10);h.assertTrue(p.getHealth()==health,"A disarmed native mob cannot cause damage through its built-in attack");});h.runAfterDelay(108,()->{heldRestored(h,m);h.assertTrue(Math.abs(p.getHealth()-900)<.01&&h.getLevel().getEntitiesOfClass(ZhanluField.class,p.getBoundingBox().inflate(6),f->f.ownedBy(p)).isEmpty(),"Eighty actual field ticks heal thirty-percent max health once and remove field");h.succeed();});}
    @GameTest(template="cauldron_pit_test",timeoutTicks=100,batch="zhanlu_artifact")
    public static void casterKillDuringFieldForfeitsHealEvenOutsideRadius(GameTestHelper h){var p=player(h);p.setHealth(600);var m=enemy(h,p,8,0);var f=field(h,p);h.runAfterDelay(10,()->m.hurt(p.damageSources().playerAttack(p),10000));h.runAfterDelay(85,()->{h.assertTrue(f.isRemoved()&&Math.abs(p.getHealth()-600)<.01,"Actual caster-attributed hostile kill anywhere during field forfeits heal");h.succeed();});}
    @GameTest(template="cauldron_pit_test",timeoutTicks=35,batch="zhanlu_artifact")
    public static void changedHandCancelsFieldAndRestoresWithoutDuplicatingEquipment(GameTestHelper h){var p=player(h);var m=enemy(h,p,0,3);var f=field(h,p);h.runAfterDelay(5,()->{h.assertTrue(ZhanluField.disarmed(m),"Real field owns equipment lease");m.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.WOODEN_SWORD));p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(ArtifactContent.ZHANLU.get()));});h.runAfterDelay(10,()->{h.assertTrue(f.isRemoved()&&m.getMainHandItem().is(Items.WOODEN_SWORD)&&m.getOffhandItem().is(Items.SHIELD)&&!ZhanluField.disarmed(m),"A second same-ID stack cannot borrow the original field; replacement equipment preserved");var drops=h.getLevel().getEntitiesOfClass(ItemEntity.class,m.getBoundingBox().inflate(3),e->e.getItem().is(Items.DIAMOND_SWORD));h.assertTrue(drops.size()==1&&drops.get(0).getItem().getDamageValue()==7,"Displaced original is returned exactly once, never overwritten or duplicated");f.cancel();h.assertTrue(h.getLevel().getEntitiesOfClass(ItemEntity.class,m.getBoundingBox().inflate(3),e->e.getItem().is(Items.DIAMOND_SWORD)).size()==1,"Repeated cancellation cannot duplicate stored equipment");h.succeed();});}
    @GameTest(template="cauldron_pit_test",timeoutTicks=40,batch="zhanlu_artifact")
    public static void twoCasterFieldsNeverCopyOneMobWeapon(GameTestHelper h){var p=player(h);var q=player(h);q.setPos(p.getX()+1,p.getY(),p.getZ());var m=enemy(h,p,.5,3);var a=field(h,p);var b=field(h,q);h.runAfterDelay(5,()->h.assertTrue(ZhanluField.disarmed(m),"One of two overlapping fields leases a mob"));h.runAfterDelay(10,()->{b.cancel();h.assertTrue(ZhanluField.disarmed(m),"Canceling the later field cannot steal the earlier lease");});h.runAfterDelay(15,()->{a.cancel();heldRestored(h,m);h.assertTrue(h.getLevel().getEntitiesOfClass(ItemEntity.class,m.getBoundingBox().inflate(3),e->e.getItem().is(Items.DIAMOND_SWORD)).isEmpty(),"One original returns to one hand, with no duplicate world drop");h.succeed();});}
    @GameTest(template="cauldron_pit_test",timeoutTicks=30,batch="zhanlu_artifact")
    public static void nativeSavedMobLeaseExpiresAndReturnsOriginalAfterReload(GameTestHelper h){var p=player(h);var m=enemy(h,p,0,3);field(h,p);h.runAfterDelay(5,()->{var n=m.saveWithoutId(new CompoundTag());n.remove("UUID");n.getCompound("ForgeData").getCompound("DynastyZhanluLeaseV1").putLong("Until",h.getLevel().getGameTime()-1);m.discard();var copy=ArtifactGameTests.own(h,EntityType.ZOMBIE.create(h.getLevel()));copy.load(n);copy.setPos(p.getX()+10,p.getY(),p.getZ());h.getLevel().addFreshEntity(copy);h.runAfterDelay(3,()->{heldRestored(h,copy);h.succeed();});});}
    @GameTest(template="cauldron_pit_test",timeoutTicks=125,batch="zhanlu_artifact")
    public static void trustedTrialHooksRejectWrongOrderDamageAndDuplicateClaims(GameTestHelper h){var p=player(h);var c=p.blockPosition().offset(1,0,0);h.getLevel().setBlock(c,TaiqingContent.SWORD_CASE.get().defaultBlockState(),3);ZhanluTrialRewards.registerSwordCase(h.getLevel(),c);h.runAfterDelay(80,()->{h.assertTrue(ZhanluTrialRewards.begin(p,c)&&!ZhanluTrialRewards.completeStage(p,c,3)&&ZhanluTrialRewards.completeStage(p,c,1),"Trusted trial hooks require exact registered case and stage order");p.hurt(p.damageSources().generic(),1);h.assertTrue(!ZhanluTrialRewards.completeStage(p,c,2),"Actual positive native damage invalidates unhurt trial");});h.runAfterDelay(105,()->{h.assertTrue(ZhanluTrialRewards.begin(p,c)&&ZhanluTrialRewards.completeStage(p,c,1)&&ZhanluTrialRewards.completeStage(p,c,2)&&ZhanluTrialRewards.completeStage(p,c,3),"Three actual server-hook completions authorize this case");p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);h.assertTrue(!ZhanluTrialRewards.claim(p,c,InteractionHand.OFF_HAND)&&ZhanluTrialRewards.claim(p,c,InteractionHand.MAIN_HAND)&&!ZhanluTrialRewards.claim(p,c,InteractionHand.MAIN_HAND),"Actual empty main hand claims once; foreign hand and replay denied");var saved=ZhanluTrialRewards.load(ZhanluTrialRewards.get(h.getLevel()).save(new CompoundTag()));var again=saved.save(new CompoundTag());h.assertTrue(again.getList("Claimed",10).stream().anyMatch(t->((CompoundTag)t).hasUUID("Id")&&((CompoundTag)t).getUUID("Id").equals(p.getUUID())),"Native SavedData preserves this one-time claim");h.succeed();});}
}
